EDGES = [
    ("client", "api"), ("api", "orders"), ("orders", "payments_adapter"),
    ("payments_adapter", "provider"), ("orders", "inventory"),
    ("api", "search"), ("search", "catalog_cache"),
]

def upstream(edges, node):
    rev = {}
    for a, b in edges:
        rev.setdefault(b, []).append(a)
    seen = set()
    stack = [node]
    while stack:
        n = stack.pop()
        for p in rev.get(n, []):
            if p not in seen:
                seen.add(p)
                stack.append(p)
    return sorted(seen)

suspect = ("payments_adapter", "provider")
blast = sorted(upstream(EDGES, suspect[0]) + [suspect[0]])
all_nodes = set(n for e in EDGES for n in e)
print(f"suspect_edge: {suspect[0]} -> {suspect[1]}")
print("blast_radius: " + ", ".join(blast))
print(f"components_affected: {len(blast)} of {len(all_nodes)}")
print("severity: checkout writes fail (charges not captured)")
print("out_of_scope: " + ", ".join(sorted(all_nodes - set(blast) - {suspect[1]})))

