STEPS = [
    ("frame", 5, True),
    ("route", 5, False),
    ("map", 3, True),
    ("decide", 4, True),
    ("proof", 2, False),
]

def calibrate(steps):
    rows = []
    gaps = []
    for name, conf, correct in steps:
        gap = round(conf / 5 - (1.0 if correct else 0.0), 2)
        gaps.append(abs(gap))
        if conf >= 4 and not correct:
            flag = "CONFIDENT_WRONG"
        elif conf <= 2 and correct:
            flag = "UNDERCONFIDENT"
        else:
            flag = "ok"
        rows.append((name, conf, correct, gap, flag))
    return rows, round(sum(gaps) / len(gaps), 2)

rows, err = calibrate(STEPS)
for name, conf, correct, gap, flag in rows:
    print(f"{name}: conf={conf}/5 correct={correct} gap={gap} {flag}")
print(f"calibration_error: {err}")
print("repair_targets: " + (", ".join(r[0] for r in rows if r[4] == "CONFIDENT_WRONG") or "none"))

