ERRORS_PER_MIN = [0, 0, 1, 0, 2, 5, 9, 14, 22, 31, 40, 44, 47, 52, 55]

def fire_minute(counts, threshold, window):
    for m in range(len(counts)):
        lo = max(0, m - window + 1)
        if sum(counts[lo : m + 1]) >= threshold:
            return m
    return -1

for name, thr, win in [("page_on_spike", 15, 3), ("daily_report", 200, 15)]:
    m = fire_minute(ERRORS_PER_MIN, thr, win)
    blast = sum(ERRORS_PER_MIN[: m + 1]) if m >= 0 else sum(ERRORS_PER_MIN)
    if m >= 0:
        print(f"{name}: fires_at_min={m} failed_requests_before_detection={blast}")
    else:
        print(f"{name}: NEVER_FIRES failed_requests_absorbed={blast}")
print("autopsy_line: detection gap = blast you eat before the signal exists")

