OPTIONS = {
    "full_rollback": {"restore_min": 8, "loses_fraud_fix": True},
    "flag_off_new_path": {"restore_min": 1, "loses_fraud_fix": False},
}

def decide(options, binding, flag_wired):
    viable = {k: v for k, v in options.items() if not (k == "flag_off_new_path" and not flag_wired)}
    return min(viable, key=lambda k: viable[k][binding])

for wired in (True, False):
    c = decide(OPTIONS, "restore_min", wired)
    print(f"flag_wired={wired} -> choice={c} time_to_restore={OPTIONS[c]['restore_min']}min")
print("reversal_condition: the choice flips when the payment-path flag wiring flips")
